import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
/*eslint-disable*/
import { formatedatetime } from "@/JsonFiles/DateFormate.js";
import BulkIndex from "@/components/TicketManagement/BulkIndex.vue";
import CreateDB from "./AllDialogs/CreateDB.vue";
import SnackBar from "@/components/SnackBar.vue";
import BulkUpload from "@/components/TicketManagement/AllDialogs/BulkUpload.vue";
import { list_cusomters_v2 } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import CustomerProduct from "@/components/TicketManagement/AllDialogs/CustomerProduct.vue";
import DeleteCustomer from "@/components/TicketManagement/AllDialogs/DeleteCustomer.vue";
export default {
  components: {
    BulkIndex,
    SnackBar,
    CreateDB,
    BulkUpload,
    CustomerProduct,
    DeleteCustomer
  },
  data() {
    return {
      height: 0,
      fixed: true,
      pagination: {
        itemsPerPage: 20,
        page: 1
      },
      nextToken: null,
      listProduct: false,
      tableData: [],
      SnackBarComponent: {},
      addmember: false,
      componentcheck: 0,
      customerdeletion: false,
      tableLoading: false,
      search: "",
      excelTableData: [],
      excelHeaders: [],
      bulkuploadDialog: false,
      headers: [{
        text: "Customer Name",
        value: "customer_name",
        sortable: false
      }, {
        text: "Contact Number",
        value: "customer_contact_number",
        sortable: false
      }, {
        text: "Email ID",
        value: "customer_email_id",
        sortable: false
      }, {
        text: "Product Name",
        value: "product_ids",
        sortable: false
      }, {
        text: "Created On",
        value: "customer_created_on",
        sortable: false
      }, {
        text: "Actions",
        value: "actions",
        sortable: false
      }

      // {
      //   text: "Created By",
      //   value: "customer_created_by",
      //   sortable: false,
      // },
      ],
      rowInfo: {}
    };
  },
  created() {
    this.height = window.innerHeight - 270;
    this.get_customers();
  },
  methods: {
    get_customer_pagination() {
      if (this.nextToken) {
        this.get_customers();
      }
    },
    open_deleteDailog(item) {
      this.rowInfo = item;
      this.componentcheck = 4;
      this.customerdeletion = true;
    },
    get_date(date) {
      return formatedatetime(date);
      // let a = new Date(date * 1000).toLocaleTimeString("en-In", {
      //   year: "numeric",
      //   month: "2-digit",
      //   day: "2-digit",
      //   hour: "2-digit",
      //   minute: "2-digit",
      //   second: "2-digit",
      // });
      // return a.toUpperCase();
    },
    openProductlist(item) {
      this.componentcheck = 3;
      this.rowInfo = item;
      this.listProduct = true;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.addmember = false;
      this.bulkuploadDialog = false;
      this.customerdeletion = false;
      this.get_customers();
    },
    handleSuccess({
      results,
      header
    }) {
      // console.log(results, header);
      this.excelTableData = results;
      this.componentcheck = 2;
      // console.log(this.exceldata.tabledata);
      this.excelHeaders = header;
      this.bulkuploadDialog = true;
      // this.$refs.editupload.getexceldata(this.exceldata);
    },
    beforeUpload(file) {
      const isLt1M = file.size / 1024 / 1024 < 1;
      if (isLt1M) {
        return true;
      }
      this.$message({
        message: "Please do not upload files larger than 1m in size.",
        type: "warning"
      });
      return false;
    },
    createCrmMember() {
      this.componentcheck = 1;
      this.addmember = true;
    },
    async get_customers() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_cusomters_v2, {
          input: {
            organization_id: data.organization.organization_id,
            //   product_id:
            // action_type: "ALL",
            limit: 101,
            NextToken: this.nextToken
          }
        }));
        this.tableLoading = false;
        // console.log(result);
        var dataArray = [];
        var response = JSON.parse(result.data.list_cusomters_v2).data;
        if (response.Status == "ERROR") {
          this.tableLoading = false;
        } else {
          this.nextToken = JSON.parse(result.data.list_cusomters_v2).nextToken;
          this.tableData = this.tableData.concat(response);
          const uniqueArrayOfObjects = this.tableData.filter((obj, index, self) => index === self.findIndex(o => o.customer_id === obj.customer_id));
          this.tableData = uniqueArrayOfObjects;
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
